//! The debug views of the renderer (contract §5.3, "Infrastructure").
//!
//! This module only names the views and gives them stable numbers; the voxel pipeline renders
//! them. It declares what it can show in a [`DebugViewSet`], keeps the selection in a
//! [`DebugViewState`] and passes [`DebugView::shader_value`] to its shaders, which compare it
//! with the constants of `common/debug_view.wgsl` (generated by [`DebugView::wgsl_constants`];
//! a test keeps the file and this enum in step).

use std::fmt;

use thiserror::Error;

/// What the frame shows instead of (or on top of) the lit image.
///
/// The discriminant is the number the shaders see; it is stable.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u32)]
pub enum DebugView {
    /// No debug view: the lit image.
    #[default]
    Off = 0,
    /// Surface albedo as stored in the G-buffer (sRGB), unlit.
    Albedo = 1,
    /// World-space normals of the G-buffer, mapped from `-1..1` to `0..1` per axis.
    Normal = 2,
    /// Reversed-Z depth (contract §2.4) as a grey ramp.
    Depth = 3,
    /// The LOD level of every chunk, one colour per level.
    LodLevel = 4,
    /// How many fragments land on each pixel, as a heat ramp.
    Overdraw = 5,
    /// The lit image with the bounds of every drawn chunk as lines.
    ChunkBounds = 6,
    /// The draw path of every chunk (contract §5.3): path A, path B, direct draws.
    DrawPath = 7,
}

impl DebugView {
    /// Every view, ordered by number.
    pub const ALL: [Self; 8] = [
        Self::Off,
        Self::Albedo,
        Self::Normal,
        Self::Depth,
        Self::LodLevel,
        Self::Overdraw,
        Self::ChunkBounds,
        Self::DrawPath,
    ];

    /// The number the shaders compare with the `DEBUG_VIEW_*` constants.
    pub const fn shader_value(self) -> u32 {
        self as u32
    }

    /// The view with shader number `value`.
    pub fn from_shader_value(value: u32) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|view| view.shader_value() == value)
    }

    /// Stable lower-case name for command lines and reports: `off`, `albedo`, `normal`,
    /// `depth`, `lod_level`, `overdraw`, `chunk_bounds`, `draw_path`.
    pub const fn id(self) -> &'static str {
        match self {
            Self::Off => "off",
            Self::Albedo => "albedo",
            Self::Normal => "normal",
            Self::Depth => "depth",
            Self::LodLevel => "lod_level",
            Self::Overdraw => "overdraw",
            Self::ChunkBounds => "chunk_bounds",
            Self::DrawPath => "draw_path",
        }
    }

    /// The view named `id` (see [`Self::id`]).
    pub fn from_id(id: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|view| view.id() == id)
    }

    /// Short description for a HUD line.
    pub const fn description(self) -> &'static str {
        match self {
            Self::Off => "lit image",
            Self::Albedo => "albedo, unlit",
            Self::Normal => "world normals",
            Self::Depth => "depth",
            Self::LodLevel => "LOD level per chunk",
            Self::Overdraw => "overdraw per pixel",
            Self::ChunkBounds => "chunk bounds",
            Self::DrawPath => "draw path per chunk",
        }
    }

    /// Name of the WGSL constant that holds this view's number: `DEBUG_VIEW_` and the id in
    /// capitals.
    pub fn wgsl_constant(self) -> String {
        format!("DEBUG_VIEW_{}", self.id().to_ascii_uppercase())
    }

    /// The text of `common/debug_view.wgsl`: one `const` per view.
    pub fn wgsl_constants() -> String {
        let mut text = String::from(
            "// Numbers of the debug views of cp_render::debug_view::DebugView, generated by\n\
             // DebugView::wgsl_constants(); a test keeps this file and the enum in step.\n\n",
        );
        for view in Self::ALL {
            text.push_str(&format!(
                "const {}: u32 = {}u;\n",
                view.wgsl_constant(),
                view.shader_value()
            ));
        }
        text
    }
}

impl fmt::Display for DebugView {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.id())
    }
}

/// A set of debug views; [`DebugView::Off`] is always in it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct DebugViewSet(u32);

impl DebugViewSet {
    /// Only [`DebugView::Off`].
    pub const OFF_ONLY: Self = Self(1);

    /// Every view.
    pub const ALL: Self = Self((1 << DebugView::ALL.len()) - 1);

    /// The set of `views` and [`DebugView::Off`].
    pub fn of(views: &[DebugView]) -> Self {
        views
            .iter()
            .fold(Self::OFF_ONLY, |set, &view| set.with(view))
    }

    /// The same set with `view` added.
    #[must_use]
    pub const fn with(self, view: DebugView) -> Self {
        Self(self.0 | (1 << view.shader_value()))
    }

    /// Whether `view` is in the set.
    pub const fn contains(self, view: DebugView) -> bool {
        self.0 & (1 << view.shader_value()) != 0
    }

    /// The views of the set, ordered by number.
    pub fn iter(self) -> impl Iterator<Item = DebugView> {
        DebugView::ALL
            .into_iter()
            .filter(move |&view| self.contains(view))
    }

    /// The view after `view` in the set, wrapping around to [`DebugView::Off`]: what a
    /// "next debug view" key selects.
    pub fn after(self, view: DebugView) -> DebugView {
        self.iter()
            .find(|&candidate| candidate > view)
            .unwrap_or(DebugView::Off)
    }
}

impl Default for DebugViewSet {
    fn default() -> Self {
        Self::OFF_ONLY
    }
}

/// A debug view was asked for that the renderer cannot show.
#[derive(Clone, Copy, Debug, Error, PartialEq, Eq)]
#[error("debug view {view} is not supported by this renderer")]
pub struct UnsupportedDebugView {
    /// The view that was asked for.
    pub view: DebugView,
}

/// The views a renderer supports and the one selected; always a supported one.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct DebugViewState {
    supported: DebugViewSet,
    current: DebugView,
}

impl DebugViewState {
    /// A state with `supported` views and [`DebugView::Off`] selected.
    pub fn new(supported: DebugViewSet) -> Self {
        Self {
            supported,
            current: DebugView::Off,
        }
    }

    /// The views the renderer can show.
    pub fn supported(&self) -> DebugViewSet {
        self.supported
    }

    /// The selected view.
    pub fn current(&self) -> DebugView {
        self.current
    }

    /// Selects `view`.
    ///
    /// # Errors
    /// [`UnsupportedDebugView`] when the renderer cannot show it; the selection stays.
    pub fn select(&mut self, view: DebugView) -> Result<(), UnsupportedDebugView> {
        if self.supported.contains(view) {
            self.current = view;
            Ok(())
        } else {
            Err(UnsupportedDebugView { view })
        }
    }

    /// Selects the next supported view (wrapping to [`DebugView::Off`]) and returns it.
    pub fn cycle(&mut self) -> DebugView {
        self.current = self.supported.after(self.current);
        self.current
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::shader::ShaderLibrary;

    #[test]
    fn numbers_and_ids_are_stable_and_unique() {
        let numbers = DebugView::ALL.map(DebugView::shader_value);
        assert_eq!(numbers, [0, 1, 2, 3, 4, 5, 6, 7]);
        let ids = DebugView::ALL.map(DebugView::id);
        assert_eq!(
            ids,
            [
                "off",
                "albedo",
                "normal",
                "depth",
                "lod_level",
                "overdraw",
                "chunk_bounds",
                "draw_path"
            ]
        );
        for view in DebugView::ALL {
            assert_eq!(DebugView::from_id(view.id()), Some(view));
            assert_eq!(
                DebugView::from_shader_value(view.shader_value()),
                Some(view)
            );
            assert_eq!(view.to_string(), view.id());
            assert!(!view.description().is_empty());
        }
        assert_eq!(DebugView::from_id("Albedo"), None);
        assert_eq!(DebugView::from_shader_value(8), None);
        assert_eq!(DebugView::default(), DebugView::Off);
        assert_eq!(DebugView::LodLevel.wgsl_constant(), "DEBUG_VIEW_LOD_LEVEL");
    }

    #[test]
    fn the_wgsl_constants_file_matches_the_enum() {
        let file = ShaderLibrary::builtin()
            .file("common/debug_view.wgsl")
            .expect("the library has the debug view constants");
        assert_eq!(
            file.source,
            DebugView::wgsl_constants(),
            "regenerate common/debug_view.wgsl from DebugView::wgsl_constants()"
        );
    }

    #[test]
    fn sets_always_hold_off_and_cycle_in_order() {
        assert!(DebugViewSet::default().contains(DebugView::Off));
        assert_eq!(DebugViewSet::default().iter().count(), 1);
        assert_eq!(DebugViewSet::ALL.iter().collect::<Vec<_>>(), DebugView::ALL);
        let set = DebugViewSet::of(&[DebugView::Depth, DebugView::Albedo]);
        assert_eq!(
            set.iter().collect::<Vec<_>>(),
            [DebugView::Off, DebugView::Albedo, DebugView::Depth]
        );
        assert!(!set.contains(DebugView::Normal));
        assert_eq!(set.after(DebugView::Off), DebugView::Albedo);
        assert_eq!(set.after(DebugView::Albedo), DebugView::Depth);
        assert_eq!(set.after(DebugView::Depth), DebugView::Off);
        // A view outside the set continues with the next one inside.
        assert_eq!(set.after(DebugView::Normal), DebugView::Depth);
        assert_eq!(DebugViewSet::OFF_ONLY.after(DebugView::Off), DebugView::Off);
    }

    #[test]
    fn the_state_only_selects_supported_views() {
        let mut state = DebugViewState::new(DebugViewSet::of(&[DebugView::Normal]));
        assert_eq!(state.current(), DebugView::Off);
        assert_eq!(
            state.select(DebugView::Overdraw),
            Err(UnsupportedDebugView {
                view: DebugView::Overdraw
            })
        );
        assert_eq!(state.current(), DebugView::Off);
        state.select(DebugView::Normal).unwrap();
        assert_eq!(state.current(), DebugView::Normal);
        assert_eq!(state.cycle(), DebugView::Off);
        assert_eq!(state.cycle(), DebugView::Normal);
        assert!(state.supported().contains(DebugView::Normal));
        assert_eq!(
            UnsupportedDebugView {
                view: DebugView::DrawPath
            }
            .to_string(),
            "debug view draw_path is not supported by this renderer"
        );
    }
}
